import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.BTt0kA_k.js";const u=JSON.parse('{"title":"构建与环境隔离","description":"","frontmatter":{},"headers":[],"relativePath":"developer/build-and-environments.md","filePath":"developer/build-and-environments.md"}'),c={name:"developer/build-and-environments.md"};function i(s,e,n,r,p,l){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="构建与环境隔离" tabindex="-1">构建与环境隔离 <a class="header-anchor" href="#构建与环境隔离" aria-label="Permalink to &quot;构建与环境隔离&quot;">​</a></h1><h2 id="构建命令" tabindex="-1">构建命令 <a class="header-anchor" href="#构建命令" aria-label="Permalink to &quot;构建命令&quot;">​</a></h2><p>在仓库根目录按需要选择：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:desktop:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:desktop:production</span></span></code></pre></div><p>前者生成开发测试安装包，后者生成正式安装包。这些命令会执行相应前端资源构建和 Rust/Tauri 打包。</p><p>只需检查前端产物时，使用 <code>pnpm build:web</code>；它生成开发环境前端资源。<code>build:assets:dev</code>、<code>build:assets:production</code> 是桌面打包流程对应的资源构建入口。</p><p>构建成功不代表签名、公证、安装和系统权限均已验证。正式发布还需核对目标架构、安装包附件与实际安装运行结果。</p><p>开发身份与 debug 编译是两个独立选项；参数传递、目标架构和跳过打包等用法见<a href="./commands.html#tauri-参数怎样传递">开发命令参考</a>。</p><h2 id="两套应用身份" tabindex="-1">两套应用身份 <a class="header-anchor" href="#两套应用身份" aria-label="Permalink to &quot;两套应用身份&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>开发与开发测试包</th><th>正式包</th></tr></thead><tbody><tr><td>应用名称</td><td>RelayPulse Dev</td><td>RelayPulse</td></tr><tr><td>应用标识</td><td><code>com.relaypulse.app.dev</code></td><td><code>com.relaypulse.app</code></td></tr><tr><td>macOS 数据目录</td><td><code>~/Library/Application Support/com.relaypulse.app.dev/</code></td><td><code>~/Library/Application Support/com.relaypulse.app/</code></td></tr><tr><td>前端资源</td><td><code>frontend/dist/development/</code></td><td><code>frontend/dist/production/</code></td></tr><tr><td>Cargo 输出</td><td><code>backend/target/development.noindex/</code></td><td><code>backend/target/production/</code></td></tr></tbody></table><p>数据库、记录文件、诊断数据、单实例锁和自启动项按应用身份隔离。开发启动不会复制正式配置；开发版看不到正式版的站点时，先核对应用名称和数据目录。</p><p>系统通知权限也按应用身份分别授予。正式版已有授权，不代表 RelayPulse Dev 已获授权；开发通知能力时，需要在开发版内检查权限和测试通知。</p><h2 id="环境选择实现" tabindex="-1">环境选择实现 <a class="header-anchor" href="#环境选择实现" aria-label="Permalink to &quot;环境选择实现&quot;">​</a></h2><p>桌面命令经 <code>scripts/tauri.mjs</code>、<code>scripts/tauri-environment.mjs</code> 包装器执行：</p><ul><li>默认使用 <code>backend/tauri.conf.json</code> 的开发身份。</li><li>正式构建通过 <code>--production</code> 叠加 <code>backend/tauri.production.conf.json</code>。</li><li>包装器设置 <code>CARGO_TARGET_DIR</code>，并清除外部 <code>TAURI_CONFIG</code>，避免开发启动意外使用正式身份。</li><li>macOS 开发启动使用 <code>scripts/macos-tauri-dev-runner.sh</code>。</li></ul><p>修改环境选择逻辑时，运行 <code>pnpm test:desktop-scripts</code>。避免绕过包装器临时覆盖配置而让开发包访问正式数据。</p><p>macOS 当前启用私有窗口 API 支持原生小面板，当前分发不面向 Mac App Store。</p><h2 id="发布版本" tabindex="-1">发布版本 <a class="header-anchor" href="#发布版本" aria-label="Permalink to &quot;发布版本&quot;">​</a></h2><p>应用版本以根目录 <code>package.json</code> 为 Tauri 配置的版本来源。发布新版本时，同步更新 <code>frontend/package.json</code>、<code>backend/Cargo.toml</code>、<code>backend/Cargo.lock</code> 中 RelayPulse 主程序条目及 <code>scripts/macos-dev-Info.plist</code>；检查桌面开发版和正式版的版本显示一致。</p><p>同时更新使用者手册适用版本、开发者文档版本日期及发布说明。变更完成后执行受影响的类型、Lint、格式和自动化测试；正式打包、签名、公证、安装验证应按发布安排另行执行。不要仅因版本号变更就推断安装包已生成或可下载。</p>`,20)])])}const m=t(c,[["render",i]]);export{u as __pageData,m as default};
